with filtered as (select id, order_id, carrier, shipped_date, cost, status, date_add(delivered_date, 14) as delivered_date_plus_14d, coalesce(carrier, 'UNKNOWN') as carrier_clean from shipments where delivered_date >= date '2023-12-03' and shipped_date <= '2024-04-01') select date_trunc('quarter', delivered_date_plus_14d) as quarter_start, size(collect_set(status)) as num_status, max(cost) as max_cost from filtered group by 1
